@php($staffIds=$registers->staff(auth()->user())->pluck('id'))
<section class="br-table-section"><h4 class="font-semibold">Attendance / Timesheet Log</h4>@if($full)<a class="hr-report-control" href="{{ route('portal.hr-reporting.attendance') }}">Attendance reporting tools</a>@endif<div class="br-table-wrap"><table class="br-table"><thead><tr><th>Staff</th><th>Clock-in</th><th>Clock-out</th><th>Status</th></tr></thead><tbody>@php($attendanceLog=\App\Models\Attendance::with('user:id,name')->whereIn('user_id',$staffIds)->whereBetween('clock_in_at',[$from.' 00:00:00',$to.' 23:59:59'])->orderByDesc('clock_in_at')->paginate(15,['*'],'hr_attendance_page')->withQueryString())@foreach($attendanceLog as $row)<tr><td>{{ $row->user?->name }}</td><td>{{ $row->clock_in_at }}</td><td>{{ $row->clock_out_at??'Not clocked out' }}</td><td>{{ $row->status }}</td></tr>@endforeach</tbody></table></div>{{ $attendanceLog->links() }}</section>
<section class="br-table-section"><h4 class="font-semibold">Leave Register</h4><a class="hr-report-control" href="{{ route('portal.leaves') }}">Leaves, balances &amp; half-day pass-outs</a><div class="br-table-wrap"><table class="br-table"><thead><tr><th>Staff</th><th>Type</th><th>Dates</th><th>Working days</th><th>Status</th><th>Remaining balance</th></tr></thead><tbody>@php($leaveLog=\App\Models\LeaveApplication::with('user:id,name,leave_balance')->whereIn('user_id',$staffIds)->whereDate('start_date','<=',$to)->whereDate('end_date','>=',$from)->latest()->paginate(15,['*'],'hr_leave_page')->withQueryString())@foreach($leaveLog as $leave)<tr><td>{{ $leave->user?->name }}</td><td>{{ ucfirst($leave->leave_type) }}</td><td>{{ $leave->start_date->toDateString() }} – {{ $leave->end_date->toDateString() }}</td><td>{{ $leave->workingDays() }}</td><td>{{ str_replace('_',' ',$leave->status) }}</td><td>{{ $leave->user?->leave_balance }}</td></tr>@endforeach</tbody></table></div>{{ $leaveLog->links() }}</section>
